--- reconcile.js ---
const fs = require('fs');
const parse = t => t.trim().split('\n').slice(1).map(l => l.split(','));
const invoices = parse(fs.readFileSync('backoffice/invoices.csv','utf8'));
const bank = parse(fs.readFileSync('backoffice/bank_statement_june.csv','utf8'));

const payments = {}; // id -> [amounts]
for (const [, memo, amt] of bank) {
  const m = memo.match(/(?:INV-)?(\d{4})/) || memo.match(/invoice (\d{4})/i);
  const idm = memo.match(/INV[- ]?(\d{4})|inv(\d{4})|invoice (\d{4})/i);
  if (!idm || /unidentified/.test(memo) || amt < 0 || /FEE|INTEREST/.test(memo)) {
    console.log('ignored:', memo, amt); continue;
  }
  const num = idm.slice(1).find(x => x);
  const id = 'INV-' + num;
  (payments[id] = payments[id] || []).push(parseFloat(amt));
}

const unpaid = [], duplicated = [], mismatched = [];
for (const [id, , amt] of invoices) {
  const p = payments[id];
  const inv = parseFloat(amt);
  if (!p) unpaid.push(id);
  else if (p.length > 1) duplicated.push(id);
  else if (Math.abs(p[0] - inv) > 0.005) mismatched.push({ id, invoiced: inv, paid: p[0] });
}
// any payment referencing unknown invoice?
for (const id of Object.keys(payments))
  if (!invoices.some(v => v[0] === id)) console.log('UNKNOWN INVOICE PAID:', id);

console.log(JSON.stringify({ unpaid, duplicated, mismatched }, null, 2));
fs.writeFileSync('result.json', JSON.stringify({ unpaid, duplicated, mismatched }, null, 2) + '\n');


